installation.script:
#!/bin/bash

echo "🚀 Installation Node.js NeoHeberg..."

mkdir -p /mnt/server
cd /mnt/server

if [ ! -f package.json ]; then
cat > package.json << 'EOF'
{
  "name": "neoheberg-nodejs-app",
  "version": "1.0.0",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {}
}
EOF
fi

if [ ! -f index.js ]; then
cat > index.js << 'EOF'
const http = require('http');

const port = process.env.SERVER_PORT;
if (!port) {
  console.error("❌ Aucun port trouvé.");
  process.exit(1);
}

const startTime = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`
<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>NeoHeberg • Node.js</title>
  <script src="https://cdn.tailwindcss.com"></script>
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/7.0.1/css/all.min.css" integrity="sha512-2SwdPD6INVrV/lHTZbO2nodKhrnDdJK9/kg2XD1r9uGqPo1cUbujc+IYdlYdEErWNu69gVcYgdxlmVmzTWnetw==" crossorigin="anonymous" referrerpolicy="no-referrer" />
</head>
<body class="bg-black text-gray-200 min-h-screen flex items-center justify-center p-4 font-sans">
  <div class="max-w-4xl w-full bg-gray-900 rounded-3xl shadow-2xl border border-gray-700 p-8 md:p-10">
    <div class="flex items-center gap-3 mb-2">
      <i class="fas fa-rocket text-4xl text-blue-400"></i>
      <h1 class="text-4xl md:text-5xl font-extrabold text-blue-400">Node.js · NeoHeberg</h1>
    </div>
    <div class="inline-block bg-green-600 text-white px-4 py-1 rounded-full text-sm font-semibold shadow-md mb-6">
      <i class="fas fa-check-circle mr-1"></i> EN LIGNE
    </div>

    <div class="grid grid-cols-1 md:grid-cols-3 gap-4 bg-gray-800 rounded-2xl p-6 shadow-inner mb-8">
      <div class="text-center md:text-left">
        <div class="text-gray-400 text-sm uppercase tracking-wider"><i class="fab fa-node-js text-lg mr-1"></i>Version Node</div>
        <div class="text-3xl font-bold text-blue-400">${process.version}</div>
      </div>
      <div class="text-center md:text-left">
        <div class="text-gray-400 text-sm uppercase tracking-wider"><i class="fas fa-plug text-lg mr-1"></i>Port</div>
        <div class="text-3xl font-bold text-blue-400">${port}</div>
      </div>
      <div class="text-center md:text-left">
        <div class="text-gray-400 text-sm uppercase tracking-wider"><i class="fas fa-clock text-lg mr-1"></i>Démarré le</div>
        <div class="text-xl font-bold text-blue-400">${startTime.split(' ')[0]}<br><span class="text-base font-normal text-gray-400">${startTime.split(' ')[1]}</span></div>
      </div>
    </div>

    <h2 class="text-2xl font-bold text-blue-400 mb-4 flex items-center gap-2"><i class="fas fa-lightbulb"></i> Exemples d'utilisation</h2>
    <div class="grid grid-cols-1 md:grid-cols-3 gap-5 mb-8">
      <div class="bg-gray-800 rounded-xl p-6 shadow-lg border-l-4 border-blue-500 hover:shadow-xl transition">
        <i class="fas fa-globe text-3xl text-blue-400 mb-3"></i>
        <h3 class="text-xl font-semibold text-white">Site web</h3>
        <p class="text-gray-300">Servez des pages HTML, CSS, JavaScript, ou utilisez Express pour créer une application web complète.</p>
      </div>
      <div class="bg-gray-800 rounded-xl p-6 shadow-lg border-l-4 border-blue-500 hover:shadow-xl transition">
        <i class="fab fa-discord text-3xl text-blue-400 mb-3"></i>
        <h3 class="text-xl font-semibold text-white">Bot Discord</h3>
        <p class="text-gray-300">Développez un bot interactif avec discord.js, gérez des commandes, de la musique, etc.</p>
      </div>
      <div class="bg-gray-800 rounded-xl p-6 shadow-lg border-l-4 border-blue-500 hover:shadow-xl transition">
        <i class="fas fa-cogs text-3xl text-blue-400 mb-3"></i>
        <h3 class="text-xl font-semibold text-white">API REST</h3>
        <p class="text-gray-300">Construisez une API légère pour votre application mobile ou votre site, avec base de données.</p>
      </div>
    </div>

    <h2 class="text-2xl font-bold text-blue-400 mb-4 flex items-center gap-2"><i class="fas fa-headset"></i> Support</h2>
    <div class="flex flex-wrap gap-4 mb-8">
      <a href="https://neoheberg.fr/" target="_blank" class="bg-gray-800 hover:bg-blue-600 text-white border border-gray-700 rounded-full px-6 py-3 font-semibold inline-flex items-center gap-2 shadow-md transition">
        <i class="fas fa-globe"></i> Site officiel
      </a>
      <a href="https://discord.neoheberg.fr/" target="_blank" class="bg-gray-800 hover:bg-blue-600 text-white border border-gray-700 rounded-full px-6 py-3 font-semibold inline-flex items-center gap-2 shadow-md transition">
        <i class="fab fa-discord"></i> Discord NeoHeberg
      </a>
    </div>

    <div class="text-center text-gray-500 text-sm border-t border-gray-700 pt-6">
      <i class="far fa-copyright mr-1"></i> 2026 <span class="font-semibold text-blue-400">NeoHeberg - Pterodactyl NodeJS Egg</span> — Tous droits réservés.</div>
  </div>
</body>
</html>
  `);
});

server.listen(port, '0.0.0.0', () => {
  console.clear();
  const now = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });
  const reset = '\x1b[0m';
  const cyan = '\x1b[36m';

  console.log(`${cyan}┌─────────────────────────────────────────────┐${reset}`);
  console.log(`${cyan}│       🚀 NeoHeberg Node.js                   │${reset}`);
  console.log(`${cyan}├─────────────────────────────────────────────┤${reset}`);
  console.log(`${cyan}│   🔥 Node version : ${process.version.padEnd(21)}    │${reset}`);
  console.log(`${cyan}│   🚪 Port : ${port.toString().padEnd(28)}     │${reset}`);
  console.log(`${cyan}│   🕒 Démarré à : ${now.padEnd(22)}      │${reset}`);
  console.log(`${cyan}├─────────────────────────────────────────────┤${reset}`);
  console.log(`${cyan}│   © 2026 NeoHeberg - Tous droits réservés   │${reset}`);
  console.log(`${cyan}│   Fait avec ❤️ par NeoHeberg                 │${reset}`);
  console.log(`${cyan}└─────────────────────────────────────────────┘${reset}`);
});

process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});
EOF
fi

echo "✅ Installation terminée."
